TILE_NAMES = ('unseen', 'empty', 'wall', 'floor', 'door', 'key', 'ball', 'box', 'goal', 'lava', 'partner', 'ego')
EGO = TILE_NAMES.index('ego')                                       # stable-marl's object types, then the agent itself

class FindGoalPOVDataset(Dataset):
    "Every agent's POV image at every step before it reached the goal, with its tiles' kinds (`TILE_NAMES`), from `collect_world.py`'s dataset."

    def __init__(self,
                 h5_path, # The dataset (`<out_dir>/dataset.h5`)
                 split: str = "train", # 'train' or 'val'
                 val_layouts=(200, 260), # The validation layouts: reset seeds [start, stop)
                 transform=None, # Applied to each frame
                ):
        assert split in ["train", "val"], "split must be 'train' or 'val'"
        self.h5_path, self.transform, self.file = h5_path, transform, None
        with h5py.File(h5_path, "r") as f:
            layout, done = f["layout"][:, 0], f["terminated"][:]
        val = (layout >= val_layouts[0]) & (layout < val_layouts[1])
        rows = val if split == "val" else ~val
        self.index = np.argwhere(rows[:, None] & ~done)              # (step, agent): agents still playing
        print(f"Initialized {split} split: {len(np.unique(layout[rows]))} layouts, {len(self.index)} agent frames.")

    def __len__(self):
        return len(self.index)

    def tiles(self, idx):
        "The kinds of the frame's tiles, `(7, 7)` as they appear in the image (the agent at the bottom centre)."
        if self.file is None:
            self.file = h5py.File(self.h5_path, "r")
        n, a = self.index[idx]
        t = self.file["image"][n, a, :, :, 0].T.astype(np.int64)     # the encoding is (x, y): rows are y
        t[-1, t.shape[1] // 2] = EGO
        return t

    def __getitem__(self, idx):
        tiles = self.tiles(idx)
        n, a = self.index[idx]
        frame = self.file["pixels"][n, a]
        if self.transform:
            frame = self.transform(frame)
        return frame, torch.from_numpy(tiles)

    def tile_frequencies(self, samples: int = 2000, seed: int = 0):
        "Each kind's share of the tiles (`TILE_NAMES` order), from `samples` frames drawn at random."
        rng = np.random.default_rng(seed)
        picks = rng.choice(len(self), min(samples, len(self)), replace=False)
        counts = np.bincount(np.concatenate([self.tiles(i).ravel() for i in picks]), minlength=len(TILE_NAMES))
        return counts / counts.sum()

    def close(self):
        if self.file is not None:
            self.file.close()
            self.file = None

