class MultiAgentWorldModelDataset(Dataset):
    def __init__(
        self,
        h5_path,
        split="train",
        val_ratio=0.1,
        history_size=3,        # T: number of frames fed to predictor
        num_preds= 1,          # number of future frames to predict (currently only supports 1)
        receiver_transform=None,
        sender_transform=None,
    ):
        assert split in ["train", "val"], "split must be 'train' or 'val'"
        self.h5_path = h5_path
        self.split = split
        self.receiver_transform = receiver_transform
        self.sender_transform = sender_transform
        self.history_size = history_size
        self.num_preds = num_preds
        self.file = None
        self.index_map = []

        with h5py.File(self.h5_path, "r") as f:
            all_episodes = sorted(list(f.keys()))
            num_episodes = len(all_episodes)
            val_count = int(num_episodes * val_ratio)
            train_count = num_episodes - val_count

            if self.split == "train":
                active_episodes = all_episodes[:train_count]
            else:
                active_episodes = all_episodes[train_count:]

            for episode_key in active_episodes:
                episode_group = f[episode_key]
                num_frames = np.min(
                    episode_group['agents_success_at']
                ).item()

                # Need history_size frames + 1 target frame
                # so valid start indices are [0, num_frames - history_size - 1]
                for start_idx in range(num_frames - history_size - num_preds):
                    # Alternate sender/receiver between agents to save training time
                    # Even indices: agent 0 is sender, agent 1 is receiver
                    # Odd indices:  agent 1 is sender, agent 0 is receiver
                    self.index_map.append((episode_key, start_idx, "0", "1"))
                    self.index_map.append((episode_key, start_idx, "1", "0"))

        print(
            f"Initialized {self.split} split with {len(active_episodes)} episodes "
            f"({len(self.index_map)} total sequence pairs)."
        )

    def __len__(self):
        return len(self.index_map)

    def __getitem__(self, idx):
        if self.file is None:
            self.file = h5py.File(self.h5_path, "r")

        episode_key, start_idx, sender_id, receiver_id = self.index_map[idx]
        episode = self.file[episode_key]
        end_idx = start_idx + self.history_size  # exclusive, this is the target frame

        # ── Receiver fields ──────────────────────────────────────────────
        # POV frames: history_size frames as input, +1 as prediction target
        receiver_pov_seq = episode[f"{receiver_id}_pov"][start_idx : end_idx + self.num_preds]  # (T+num_preds, H, W, C)
        receiver_act_seq = episode[f"{receiver_id}_act"][start_idx : end_idx]      # (T,)

        # ── Sender fields ─────────────────────────────────────────────────
        # We only need the sender's POV at the last history frame
        # (the frame whose encoding becomes the message)
        # sender_pov = episode[f"{sender_id}_pov"][end_idx - 1]                      # (H, W, C)
        # sender_csi = episode[f"{sender_id}_csi"][end_idx - 1]                      # complex scalar

        sender_pov_seq = episode[f"{sender_id}_pov"][start_idx : end_idx]  # (T, H, W, C)
        sender_csi_seq = episode[f"{sender_id}_csi"][start_idx : end_idx]  # (T,) complex

        # ── Apply transforms to POV frames ────────────────────────────────
        if self.receiver_transform:
            # Transform each frame independently
            receiver_pov_seq = torch.stack(
                [self.receiver_transform(receiver_pov_seq[t]) for t in range(self.history_size + 1)]
            )                    
            
        else:
            receiver_pov_seq = torch.from_numpy(receiver_pov_seq).float() / 255.0
            
                                                                # (T+1, C, H, W)
        if self.sender_transform:
            # sender_pov = self.sender_transform(sender_pov)                                 # (C, H, W)
            sender_pov = torch.stack(
                [self.sender_transform(sender_pov_seq[t]) for t in range(self.history_size)]
            )  
            
        else:
            sender_pov = torch.from_numpy(sender_pov_seq).float() / 255.0

        return {
            # Receiver inputs
            "pixels": receiver_pov_seq,           # (T+1, C, H, W) — first T are history, last is target
            "action": torch.tensor(
                receiver_act_seq, dtype=torch.long
            ),                                               # (T,) discrete actions

            # Sender inputs (for VQ-VAE message extraction)
            "sender_pov": sender_pov,                       # (C, H, W)
            "sender_csi": torch.tensor(
                sender_csi_seq, dtype=torch.complex64
            ),                                               # scalar complex
        }

    def close(self):
        if self.file is not None:
            self.file.close()
            self.file = None
    

# %% ../../nbs/01a_data.datasets.ipynb #d2f0b002
def _relative_pose(sender_pos, sender_dir, receiver_pos, receiver_dir):
    "`models.jepa.relative_pose` in numpy: (cells ahead, cells to the right, quarter turns)."
    vec = np.array(((1, 0), (0, 1), (-1, 0), (0, -1)))
    ahead = vec[receiver_dir]
    right = np.stack([-ahead[..., 1], ahead[..., 0]], -1)
    d = sender_pos - receiver_pos
    return np.stack([(d * ahead).sum(-1), (d * right).sum(-1), (sender_dir - receiver_dir) % 4], -1)

class FindGoalWorldModelDataset(Dataset):
    "Windows of a receiver's frames and actions, with the other agents' messages before and during them, from `collect_world.py`'s dataset."

    def __init__(self,
                 h5_path, # The dataset (`<out_dir>/dataset.h5`)
                 split: str = "train", # 'train' or 'val'
                 val_layouts=(200, 260), # The validation layouts: reset seeds [start, stop)
                 history_size: int = 3, # Frames fed to the predictor
                 num_preds: int = 1, # Frames predicted after them
                 tokens=None, # Each frame's VQ tokens, (steps, agents, 49) (`encode_tokens`); None: no messages
                 max_age: int = 8, # Messages sent this many steps before the window are included
                 transform=None, # Applied to each frame
                ):
        assert split in ["train", "val"], "split must be 'train' or 'val'"
        self.h5_path, self.transform, self.file = h5_path, transform, None
        self.history_size, self.num_preds, self.max_age = history_size, num_preds, max_age
        self.tokens = np.load(tokens, mmap_mode="r") if isinstance(tokens, (str, os.PathLike)) else tokens
        with h5py.File(h5_path, "r") as f:
            layout, done, action = f["layout"][:, 0], f["terminated"][:], f["action"][:]
            self.position, self.direction = f["position"][:], f["direction"][:]
            offset, length = f["ep_offset"][:], f["ep_len"][:]
        self.done = done
        self.episode_start = np.repeat(offset, length)                 # each row's episode's first row
        val = (layout >= val_layouts[0]) & (layout < val_layouts[1])
        keep = val if split == "val" else ~val
        T, span = history_size, history_size + num_preds
        playing = ~done & np.isfinite(action)                          # (rows, agents): acting at this row
        index = []
        for o, n in zip(offset, length):
            if n < span or not keep[o]:
                continue
            ok = playing[o:o + n]
            run = np.cumsum(np.vstack([np.zeros((1, ok.shape[1]), int), ~ok]), axis=0)
            starts = np.arange(n - span + 1)
            good = (run[starts + T] - run[starts]) == 0                 # acting at every history step
            index += [(o + s, a) for s, a in np.argwhere(good)]
        self.index = np.array(index, dtype=np.int64).reshape(-1, 2)    # (first row, receiver)
        self.agents = done.shape[1]
        print(f"Initialized {split} split: {len(np.unique(layout[keep]))} layouts, {len(self.index)} windows.")

    def __len__(self):
        return len(self.index)

    def __getitem__(self, idx):
        if self.file is None:
            self.file = h5py.File(self.h5_path, "r")
        r, i = self.index[idx]
        T, span = self.history_size, self.history_size + self.num_preds
        pixels = self.file["pixels"][r:r + span, i]                        # (T + num_preds, H, W, C)
        action = self.file["action"][r:r + T, i]
        frames = [self.transform(p) if self.transform else torch.from_numpy(p).permute(2, 0, 1).float() / 255.0
                  for p in pixels]
        out = {"pixels": torch.stack(frames), "action": torch.as_tensor(action, dtype=torch.long)}
        if self.tokens is None:
            return out

        senders = [j for j in range(self.agents) if j != i]
        rows = np.arange(r - self.max_age, r + T)                         # the memory, then the history
        inside = rows >= self.episode_start[r]
        rows = np.maximum(rows, self.episode_start[r])
        sent = inside[:, None] & ~self.done[rows][:, senders]             # a sender at the goal sends no more
        pose = _relative_pose(self.position[rows][:, senders], self.direction[rows][:, senders],
                              self.position[rows, i][:, None], self.direction[rows, i][:, None])
        out.update(msg_tokens=torch.as_tensor(np.asarray(self.tokens[rows][:, senders]), dtype=torch.long),
                   msg_sent=torch.as_tensor(sent), msg_pose=torch.as_tensor(pose, dtype=torch.long))
        return out

    def close(self):
        if self.file is not None:
            self.file.close()
            self.file = None

# %% ../../nbs/01a_data.datasets.ipynb #3055a55b
class MultiAgentPlanningDataset(Dataset):
    """
    Dataset for online planning evaluation. Unlike MultiAgentWorldModelDataset
    (which yields single sender/receiver training windows), this yields one
    full episode at a time for *both* agents, so the evaluator can choose its
    own t0 / goal_offset and build messages for either agent acting as sender.

    Returns, per episode:
        {
            "agent_0": {"pixels": (T, C, H, W), "action": (T,)},
            "agent_1": {"pixels": (T, C, H, W), "action": (T,)},
            "episode_key": str,
            "length": int,
        }
    """

    def __init__(
        self,
        h5_path,
        split="train",
        val_ratio=0.1,
        agents=("0", "1"),
        jepa_transform=None,
        vqvae_transform=None,
        max_length=None,
        min_length= 1
    ):
        assert split in ["train", "val"], "split must be 'train' or 'val'"
        self.h5_path = h5_path
        self.split = split
        self.agents = list(agents)
        self.jepa_transform = jepa_transform
        self.vqvae_transform = vqvae_transform
        self.max_length = max_length
        self.file = None

        with h5py.File(self.h5_path, "r") as f:
            all_episodes = sorted(list(f.keys()))

            # drop episodes with degenerate (<= 0, or < min_length) success horizon
            valid_episodes = [
                k for k in all_episodes
                if np.min(f[k]["agents_success_at"]) >= min_length and f[k]['agents_success_at'][0] > 0 and f[k]['agents_success_at'][1] > 0
            ]
            dropped = len(all_episodes) - len(valid_episodes)
            if dropped:
                print(f"[MultiAgentPlanningDataset] dropped {dropped} degenerate episode(s) "
                    f"with success_at < {min_length}")
                
            num_episodes = len(valid_episodes)
            val_count = int(num_episodes * val_ratio)
            train_count = num_episodes - val_count
            self.episode_keys = (
                valid_episodes[:train_count] if split == "train" else valid_episodes[train_count:]
            )

        print(f"Initialized {self.split} planning split with {len(self.episode_keys)} episodes.")

    def __len__(self):
        return len(self.episode_keys)

    def _load_agent(self, episode, agent_id, length):
        pov_seq = episode[f"{agent_id}_pov"][:length]       # (T, H, W, C)
        act_seq = episode[f"{agent_id}_act"][:length]        # (T,)
        csi_seq = episode[f"{agent_id}_csi"][:length]        # (T,) complex
        pos_seq = episode[f"{agent_id}_pos"][:length]        # (T, 2) position
        dir_seq = episode[f"{agent_id}_dir"][:length]        # (T,) direction

        if self.jepa_transform:
            pov_seq = torch.stack([self.jepa_transform(pov_seq[t]) for t in range(length)])  # (T, C, H, W)

        if self.vqvae_transform:
            pov_seq_vqvae = torch.stack([self.vqvae_transform(pov_seq[t]) for t in range(length)])  # (T, C, H, W)

        act_seq = torch.tensor(act_seq, dtype=torch.long)  # (T,)
        csi_seq = torch.tensor(csi_seq, dtype=torch.complex64)  # (T,)
        pos_seq = torch.tensor(pos_seq, dtype=torch.long)  # (T, 2)
        dir_seq = torch.tensor(dir_seq, dtype=torch.long)  # (T,)
        return pov_seq, act_seq, pov_seq_vqvae, csi_seq, pos_seq, dir_seq

    def __getitem__(self, idx):
        if self.file is None:
            self.file = h5py.File(self.h5_path, "r")

        episode_key = self.episode_keys[idx]
        episode = self.file[episode_key]

        # success_at = np.asarray(episode["agents_success_at"]) 
        length = np.min(episode["agents_success_at"]).item()

        if self.max_length is not None:
            length = min(length, self.max_length)

        out = {
            "episode_key": episode_key,
            "length": length,
            "goal_pos": torch.tensor(episode["goal_pos"], dtype=torch.long),
            "goal_obs": torch.stack([
                self.jepa_transform(episode["goal_obs"][i]) for i in range(len(self.agents))
            ]),  # (n_agents, C, H, W),  
        }

        for agent_id in self.agents:
            pixels, action, pov_seq_vqvae, csi_seq, pos_seq, dir_seq = self._load_agent(episode, agent_id, length)

            info = {
                        "pixels": pixels,
                        "action": action,
                        "pov_seq_vqvae": pov_seq_vqvae,
                        "csi": csi_seq,
                        "pos": pos_seq,
                        "dir": dir_seq,
                        "success_at": torch.tensor(episode['agents_success_at'][int(agent_id)], dtype=torch.long) # 
                    }
            
            out[f"agent_{agent_id}"] = info

        return out

    def close(self):
        if self.file is not None:
            self.file.close()
            self.file = None
            
